# patch_20261010_marketing_licensee_live.ps1
# /marketing segment: skip mills linked to MBG licensees (Omya / Specialty Minerals)
# read live from app.party_supply_links. Replaces 3 files ONLY if each still matches
# the expected original (LF-normalized SHA-256); otherwise it stops and changes nothing.
# Idempotent: a file already at the new content is skipped. ASCII output only.
$Repo = "C:\dev\mbg-project"
function Sha([string]$t) { $b = [System.Text.Encoding]::UTF8.GetBytes($t); $h = [System.Security.Cryptography.SHA256]::Create().ComputeHash($b); ($h | ForEach-Object { $_.ToString("x2") }) -join "" }
$items = @(
  @{ Path = "src\lib\queries\marketing-segment.ts"; Old = "fa64b6287d6e105b070e34ec4aa818a5e6f73625eaad4618acf840eb77c60d5c"; New = "8981804a987a6faebc81f4497194520bddb9826bc21f8656be25201b400dd61f"; B64 = "" },
  @{ Path = "src\lib\actions\marketing-segment.ts"; Old = "524d0f878632fa58bee43774407087f2561047fc672bda28a70a1e56ec4e7816"; New = "f15f832b799d1fe442a9358e5c64bc98356245af06e8a3680bd36213595e1f4f"; B64 = "" },
  @{ Path = "src\app\(app)\marketing\marketing-client.tsx"; Old = "66388f4e4865a30abaf1e41835f00b1e411bd5802465c71840eb32f175641544"; New = "07c5c67aaa1bec85f25ce23f29f61dc5c5b9fb47056c155b99304ce9a94f1a77"; B64 = "" }
)
# pass 1: verify all before writing any
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  if (-not (Test-Path -LiteralPath $p)) { Write-Output ("ERROR missing " + $it.Path); return }
  $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
  if ($cur -ne $it.Old -and $cur -ne $it.New) { Write-Output ("ERROR changed since review, not patched: " + $it.Path); return }
}
# pass 2: write
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
  if ($cur -eq $it.New) { Write-Output ("SKIP  already patched " + $it.Path); continue }
  $bytes = [System.Convert]::FromBase64String($it.B64)
  [System.IO.File]::WriteAllBytes($p, $bytes)
  Write-Output ("PATCHED " + $it.Path)
}
